"""Combine the Python type stubs with docstrings from the installed Rust bindings."""

import argparse
import ast
from pathlib import Path


SOURCE = Path(__file__).with_name("delta_arrow_reader.pyi")
OUTPUT = (
    Path(__file__).resolve().parents[1]
    / "delta-arrow-reader-core/docs/python_api/delta_arrow_reader/__init__.pyi"
)
HEADER = """# Generated by crates/delta-arrow-reader-python/generate_api_docs.py.
# Do not edit. Update the Rust binding comments or the Python type stubs instead.

"""


def set_docstring(node, docstring):
    if ast.get_docstring(node, clean=False) is not None:
        node.body.pop(0)
    if docstring:
        node.body.insert(0, ast.Expr(value=ast.Constant(value=docstring)))


def render(stub, module):
    tree = ast.parse(stub)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        native = getattr(module, node.name)
        set_docstring(node, native.__doc__)
        for member in node.body:
            if not isinstance(member, ast.FunctionDef):
                continue
            # PyO3 puts constructor documentation on the class, not object.__init__.
            docstring = None if member.name == "__init__" else getattr(native, member.name).__doc__
            set_docstring(member, docstring)
    return HEADER + ast.unparse(tree) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the generated API file is stale.")
    arguments = parser.parse_args()

    import delta_arrow_reader

    rendered = render(SOURCE.read_text(encoding="utf-8"), delta_arrow_reader)
    if arguments.check:
        # Compare syntax trees so Python formatter changes do not invalidate the snapshot.
        current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.is_file() else ""
        if ast.dump(ast.parse(current)) != ast.dump(ast.parse(rendered)):
            raise SystemExit(
                "Python API documentation is stale. Rebuild the Python bindings, then run "
                "python crates/delta-arrow-reader-python/generate_api_docs.py"
            )
        print("Python API documentation is current.")
    else:
        OUTPUT.parent.mkdir(parents=True, exist_ok=True)
        OUTPUT.write_text(rendered, encoding="utf-8")
        print(f"Updated {OUTPUT}")


if __name__ == "__main__":
    main()
